import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, fingerprint, next_run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const workerHeartbeat = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'");

const MAX_BODY_BYTES = 64 * 1024;
const MAX_INPUT_LENGTH = 1000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const WORKER_LIVENESS_MS = 3000;

interface FieldIssue {
  field: string;
  message: string;
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldIssue[]): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendJson(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allowed.join(', ')}.` } },
    { allow: allowed.join(', ') },
  );
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function mediaType(req: IncomingMessage): string {
  const header = req.headers['content-type'];
  return typeof header === 'string' ? header.split(';')[0]!.trim().toLowerCase() : '';
}

/** Parses and validates a submission body. Problems are appended to `fields`; returns null if any exist. */
function parseBody(text: string, fields: FieldIssue[]): Submission | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    fields.push({ field: 'body', message: 'Body is not valid JSON.' });
    return null;
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object.' });
    return null;
  }
  const obj = parsed as Record<string, unknown>;
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  const before = fields.length;
  for (const key of Object.keys(obj)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'Required.' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string.' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `Must be 1-${MAX_INPUT_LENGTH} characters.` });
  } else if (obj.input.trim().length === 0) {
    fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  } else {
    input = obj.input;
  }

  const steps = intField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = intField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > before) return null;
  return { input, steps, failAttempts };
}

function intField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldIssue[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return v;
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const fields: FieldIssue[] = [];

  let idempotencyKey: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_RE.test(keyHeader)) idempotencyKey = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  let submission: Submission | null = null;
  if (mediaType(req) !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (body.tooLarge) {
    fields.push({ field: 'body', message: 'Body is too large.' });
  } else {
    submission = parseBody(body.text, fields);
  }

  if (fields.length > 0 || submission === null) {
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
  }

  const fingerprint = JSON.stringify([submission.input, submission.steps, submission.failAttempts]);
  if (idempotencyKey !== null) {
    const existing = selectByKey.get(idempotencyKey) as unknown as JobRow | undefined;
    if (existing) {
      if (existing.fingerprint === fingerprint) return sendJson(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  const id = randomUUID();
  const at = new Date().toISOString();
  insertJob.run(id, submission.input, submission.steps, submission.failAttempts, idempotencyKey, fingerprint, at, at);
  const row = selectById.get(id) as unknown as JobRow;
  sendJson(res, 201, toJob(row));
}

function isWorkerUp(): boolean {
  const row = workerHeartbeat.get() as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at <= WORKER_LIVENESS_MS;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp() ? 'up' : 'down' });
  }
  if (path === '/api/jobs') {
    if (method === 'GET') {
      const rows = selectAll.all() as unknown as JobRow[];
      return sendJson(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = selectById.get(id) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return sendJson(res, 200, toJob(row));
  }
  return sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e) => {
    console.error('request failed', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

