3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Job tracker</title>
7	  <style>
8	    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #1a1a1a; }
9	    form { display: grid; grid-template-columns: 1fr 6rem 8rem auto; gap: .5rem; align-items: end; }
10	    label { display: flex; flex-direction: column; font-size: .85rem; gap: .2rem; }
11	    input { padding: .4rem; font: inherit; }
12	    button { padding: .45rem .9rem; font: inherit; cursor: pointer; }
13	    [role="alert"]:not(:empty) { margin: 1rem 0; padding: .6rem; border: 1px solid #b00020; color: #b00020; background: #fdecef; border-radius: 4px; }
14	    ul { list-style: none; padding: 0; }
15	    li { border-bottom: 1px solid #ddd; padding: .6rem 0; display: grid; grid-template-columns: 1fr auto auto; gap: .75rem; align-items: baseline; }
16	    .meta { font-size: .8rem; color: #555; }
17	    .status-completed { color: #0a7a2f; }
18	    .status-failed { color: #b00020; }
19	  </style>
20	</head>
21	<body>
22	  <h1>Job tracker</h1>
23	
24	  <form data-testid="job-form" id="job-form" novalidate>
25	    <label>Input
26	      <input data-testid="job-input" id="job-input" name="input" type="text" autocomplete="off">
27	    </label>
28	    <label>Steps
29	      <input data-testid="job-steps" id="job-steps" name="steps" type="text" inputmode="numeric" value="5">
30	    </label>
31	    <label>Fail attempts
32	      <input data-testid="job-fail-attempts" id="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
33	    </label>
34	    <button data-testid="job-submit" type="submit">Submit</button>
35	  </form>
36	
37	  <div data-testid="form-error" id="form-error" role="alert"></div>
38	
39	  <ul data-testid="job-list" id="job-list" aria-label="Jobs"></ul>
40	
41	<script>
42	  const form = document.getElementById('job-form');
43	  const inputEl = document.getElementById('job-input');
44	  const stepsEl = document.getElementById('job-steps');
45	  const failEl = document.getElementById('job-fail-attempts');
46	  const errorEl = document.getElementById('form-error');
47	  const listEl = document.getElementById('job-list');
48	
49	  // Numeric-looking text is sent as a number so the API's own validation applies. Empty means "use the default".
50	  function fieldValue(raw) {
51	    const s = raw.trim();
52	    if (s === '') return undefined;
53	    return /^[+-]?\d+(\.\d+)?$/.test(s) ? Number(s) : s;
54	  }
55	
56	  function renderJobs(jobs) {
57	    const items = jobs.map((job) => {
58	      const li = document.createElement('li');
59	      li.dataset.testid = 'job-item';
60	      li.dataset.jobId = job.id;
61	
62	      const name = document.createElement('span');
63	      name.textContent = job.input;
64	      const meta = document.createElement('div');
65	      meta.className = 'meta';
66	      meta.textContent = `attempts ${job.attempts} · ${job.createdAt}`;
67	      name.appendChild(meta);
68	
69	      const status = document.createElement('span');
70	      status.dataset.testid = 'job-status';
71	      status.className = 'status-' + job.status;
72	      status.textContent = job.status;
73	
74	      const progress = document.createElement('span');
75	      progress.dataset.testid = 'job-progress';
76	      progress.textContent = `${job.progress.completed}/${job.progress.total}`;
77	
78	      const result = document.createElement('span');
79	      result.dataset.testid = 'job-result';
80	      if (job.status === 'completed' && job.result) result.textContent = job.result.output;
81	      else if (job.status === 'failed' && job.error) result.textContent = job.error;
82	      else result.textContent = '';
83	
84	      li.append(name, status, progress, result);
85	      return li;
86	    });
87	    listEl.replaceChildren(...items);
88	  }
89	
90	  async function refresh() {
91	    try {
92	      const res = await fetch('/api/jobs');
93	      if (!res.ok) return;
94	      const body = await res.json();
95	      renderJobs(body.jobs);
96	    } catch {
97	      // Keep the last rendered list; the next poll will try again.
98	    }
99	  }
100	
101	  form.addEventListener('submit', async (event) => {
102	    event.preventDefault();
103	    errorEl.textContent = '';
104	    const body = { input: inputEl.value };
105	    const steps = fieldValue(stepsEl.value);
106	    const failAttempts = fieldValue(failEl.value);
107	    if (steps !== undefined) body.steps = steps;
108	    if (failAttempts !== undefined) body.failAttempts = failAttempts;
109	
110	    try {
111	      const res = await fetch('/api/jobs', {
112	        method: 'POST',
113	        headers: { 'content-type': 'application/json' },
114	        body: JSON.stringify(body),
115	      });
116	      const data = await res.json().catch(() => null);
117	      if (res.status === 201 || res.status === 200) {
118	        inputEl.value = '';
119	        await refresh();
120	        return;
121	      }
122	      const error = data && data.error;
123	      if (error && Array.isArray(error.fields) && error.fields.length > 0) {
124	        errorEl.textContent = (error.message || 'Rejected.') + ' ' +
125	          error.fields.map((f) => `${f.field}: ${f.message}`).join(' ');
126	      } else {
127	        errorEl.textContent = (error && error.message) || `Request failed (${res.status}).`;
128	      }
129	    } catch {
130	      errorEl.textContent = 'Could not reach the server.';
131	    }
132	  });
133	
134	  refresh();
135	  setInterval(refresh, 1000);
136	</script>
137	</body>
